import{_ as d,c as r,o as s,a0 as e}from"./chunks/framework.C1J0Vcxi.js";const a="/assets/2026-08-23-k3-ipc-fig1-budget-waterfall.BBtC_m1p.png",o="/assets/2026-08-23-k3-ipc-fig2-op-unit-price.CtIylG1Z.png",n="/assets/2026-08-23-k3-ipc-fig3-rp-message-budget.BOUi0SiI.png",c="/assets/2026-08-23-k3-ipc-fig4-mtime-trap.Bo8otlL1.png",i="/assets/2026-08-23-k3-ipc-fig5-roadmap.MIwED5DZ.png",_=JSON.parse('{"title":"K3 IPC 延迟归因与优化总结报告","description":"","frontmatter":{},"headers":[],"relativePath":"技术报告/2026-08-23-K3-IPC延迟归因与优化总结报告.md","filePath":"技术报告/2026-08-23-K3-IPC延迟归因与优化总结报告.md"}'),l={name:"技术报告/2026-08-23-K3-IPC延迟归因与优化总结报告.md"};function h(g,t,p,b,m,u){return s(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="k3-ipc-延迟归因与优化总结报告" tabindex="-1">K3 IPC 延迟归因与优化总结报告 <a class="header-anchor" href="#k3-ipc-延迟归因与优化总结报告" aria-label="Permalink to &quot;K3 IPC 延迟归因与优化总结报告&quot;">​</a></h1><p><strong>时间跨度</strong>：2026-08-16 至 08-23（八天，约 20 轮真板测量） <strong>对象</strong>：K3 COM260 真板，AP（X100 大核，StarryOS/Linux）与 RP（RT24 小核 @~246MHz，rt-async RTOS）之间的跨核 RPC <strong>结果</strong>：单条 PING 往返 <strong>294µs → 236.9µs（−19.5%）</strong>；此外查明并定性了一个正确性缺陷（A4：cbo.flush 静默丢发布，见附录 B；处置为检测而非运行时恢复） <strong>本文目的</strong>：完整说明每一微秒消耗在哪个环节、每种操作的单价是多少、各项优化成功或失败的原因。</p><blockquote><p>全部数据为真板实测（dd 场景闭环残差 30/30 = 0.0，AP/RP 双时钟交叉校验）。 图表由随文脚本 <code>2026-08-23-K3-IPC延迟归因-make_figs.py</code> 生成（在本目录下运行可重新生成 5 张 PNG）。 本文为 2026-08-23 收官归档版（自主仓 <code>docs/latency-report/REPORT.md</code> 迁入）；测量载体 （user-test-bench 的 dd/mb 场景、RP 侧 intercom 探针）在主仓 rt-async-amp。</p></blockquote><hr><h2 id="_0-概要" tabindex="-1">0. 概要 <a class="header-anchor" href="#_0-概要" aria-label="Permalink to &quot;0. 概要&quot;">​</a></h2><p><strong>总体结论</strong>：跨核 RPC 慢，主要不是协议和数据搬运的问题，而是两类不易察觉的固定开销—— <strong>内存序 fence</strong>（每次约 2.2µs，一条消息约需 14 次，合计约 31µs）和<strong>计时器冷读</strong> （mtime 只要有间隔再读就需要 24.5µs，原因是跨时钟域同步器重新锁定）。对应措施：减少 fence 次数（P3，已完成）；更换计时器做过两次尝试，均被证伪（冷读开销在真实路径上从未 被支付，详见 §6.2）；另查明并定性了优化过程中发现的缓存写回丢失问题（A4，定性完成； 按设计决策不设运行时恢复，由检测测试判定其存在性，见附录 B）。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以 P1 之后的 240µs 基线分解（P3 之后实测 236.9µs，构成相同）：</span></span>
<span class="line"><span>   AP 发送 8.5  →  门铃+唤醒链 ~40  →  RP 取包+分发 ~75  →  响应+门铃 ~20</span></span>
<span class="line"><span>   →  AP 收到 25  →  其中约 50µs 来自计时器读取和内存序 fence 的额外开销</span></span></code></pre></div><p><strong>三项主要发现</strong>（决定了整个优化方向）：</p><table tabindex="0"><thead><tr><th>#</th><th>发现</th><th>实测</th><th>影响</th></tr></thead><tbody><tr><td>1</td><td><strong>fence 恒定 2.2µs/次</strong>（Acquire 读实际是 <code>ld</code> + <code>fence r,rw</code>）</td><td>四种口径均为 2198-2222ns</td><td>每条消息热路径约 14 次 fence，合计约 31µs；这是内存序的固有开销，只能通过减少次数降低</td></tr><tr><td>2</td><td><strong>mtime 计时器冷读 24µs/次</strong>（间隔超过约 15µs 后跨时钟域同步器重新锁定）</td><td>热循环 106ns，间隔 20µs 后 24.5µs（231 倍）；mcycle CSR 冷读更慢（约 2.9ms；热读仅 17ns，按核频 245.84MHz 计数）</td><td>每条消息的计时与统计链占用 24-48µs（生产构建）或 40-70µs（测量构建）——既是真实的执行开销，也污染了所有分段测量</td></tr><tr><td>3</td><td><strong>W2 双向轮询实测 −11µs</strong>（AP 响应方向改为用户态自旋，免 syscall 与内核唤醒）</td><td>rtt 189→178，零固件改动</td><td>路线图中成本最低的下一步，预演已成功</td></tr></tbody></table><p><strong>优化进展一览</strong>（详见 §6，图 5）：</p><table tabindex="0"><thead><tr><th>项</th><th>结果</th></tr></thead><tbody><tr><td>P1 本地原子 + timer 直连 + 别名窗 + mailbox 去 Acquire</td><td>已完成：rtt 294→240 / D2 209→189</td></tr><tr><td>P3 fence 去冗余</td><td>已验收：同一次启动内 A/B 对比 −10µs（246.9→236.9），自旋 18→9.4µs/轮</td></tr><tr><td>更换计时源（counter1 / AON_TIMER1 两个候选）</td><td>已证伪并回滚：两次尝试均无效果，结论为计时源在生产路径中性</td></tr><tr><td>P2 ISR 直派</td><td>已否决：不破坏 rt-async 任务模型</td></tr><tr><td>A4 缓存写回丢失（cbo.flush 静默丢发布）</td><td>已定性并验证（附录 B）；按设计决策不设运行时恢复，fresh_scan 兼作存在性检测</td></tr><tr><td>W2 双向轮询产品化</td><td>待实施：预演已实测 −11µs</td></tr></tbody></table><h3 id="术语说明" tabindex="-1">术语说明 <a class="header-anchor" href="#术语说明" aria-label="Permalink to &quot;术语说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td>AP / RP</td><td>大核 X100（运行 Linux）／小核 RT24（运行 rt-async RTOS）</td></tr><tr><td>rtt</td><td>一条 PING 请求的完整往返时间</td></tr><tr><td>D1 / D2 / D3 / D4</td><td>RP 发现请求的四种路径：D1 门铃唤醒（间隔 &gt;2s）/ D2 弹性自旋命中（&lt;2s，无需门铃和 syscall）/ D3 批处理追加 / D4 竞态兜底</td></tr><tr><td>W</td><td>RP 的弹性自旋窗口时长（实测约 2s）：发送间隔短于该值即走 D2，无需门铃</td></tr><tr><td>send</td><td>AP 用户态写请求并发布缓存的耗时</td></tr><tr><td>ddrain / ddisp</td><td>RP 中断服务里的 mailbox 排空 ／ trap 返回 + 调度 + 执行器派发</td></tr><tr><td>dseen</td><td>RP 任务恢复到 handler 入口的总段，细分为 dpre（弹性前缀）/ drx（try_recv 取包）/ dserde（分发与反序列化）</td></tr><tr><td>didx / dslot / drest</td><td>更细的探针分段：索引读取 ／ 消息槽读取 ／ dispatch 宏与 postcard</td></tr><tr><td>S / APret</td><td>S = 去程门铃 + RP 服务尾 + 响应门铃（与两钟相位差无关的量）；APret = AP 从收到 IRQ 到用户态读完响应</td></tr><tr><td>fence / Acquire / Release</td><td>RISC-V 内存序指令；RP 上一条 Acquire 读约等于一次 fence，约 2.2µs</td></tr><tr><td>SPSC</td><td>单生产者单消费者环形队列（ov-channels 通道结构：magic 头 + 读/写索引 + 128×256B 消息槽）</td></tr><tr><td>CBO / user-cbo</td><td>Zicbom 缓存维护指令（flush 为写回脏行，inval 为作废驻留副本）；user-cbo 指 AP 用户态按行自行做缓存维护，跳过内核整窗刷新</td></tr><tr><td>mtime / mcycle / counter1 / AON_TIMER1</td><td>四个候选计时器：mtime（SoC 共享块，跨域）/ mcycle（CSR，核频）/ counter1（AP 域 APB）/ AON_TIMER1（RP 本地域）</td></tr><tr><td>stamps</td><td>测量构建（probe feature）在 RPC 各阶段记录的 mtime 时间戳</td></tr><tr><td>闭环残差</td><td>rtt 与各分段之和的差值，应恒为 0，用于证明整套测量自洽</td></tr><tr><td>探针结果不等于生产结果</td><td>探针（隔离微基准）测得的价格与真实路径中的价格不同——本次工作最重要的方法学结论</td></tr><tr><td>同一次启动内的 A/B 对比</td><td>dd 数据只在同一次开机内可比——跨启动存在环境差异漂移（见 §6.2）</td></tr></tbody></table><hr><h2 id="_1-系统与一条消息的处理流程" tabindex="-1">1. 系统与一条消息的处理流程 <a class="header-anchor" href="#_1-系统与一条消息的处理流程" aria-label="Permalink to &quot;1. 系统与一条消息的处理流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────┐   写请求槽+索引       ┌──────────────┐    读槽+分发+响应</span></span>
<span class="line"><span>│ AP 大核  │ ──cbo发布──▶ 共享窗  │ ◀──────────  │  RP 小核 rt-async</span></span>
<span class="line"><span>│ Linux   │   SRAM 100KB         │   弹性自旋/IRQ │  614/491MHz RTOS</span></span>
<span class="line"><span>└────┬────┘                      └──────────────┘</span></span>
<span class="line"><span>     │  ▲ mailbox 门铃（硬件 FIFO，IRQ 3463ns/次）</span></span>
<span class="line"><span>     ▼  │</span></span>
<span class="line"><span>   AWAIT ioctl（内核睡眠等响应）</span></span></code></pre></div><ul><li><strong>通道结构</strong>（ov-channels SPSC 环）：ch0 请求（AP→RP）、ch1 响应（RP→AP）、ch2 急停。每通道 = magic 头 + 读写索引（同一 cache line）+ 128×256B 消息槽。</li><li><strong>四种发现路径</strong>：D1 门铃唤醒（间隔 &gt;2s）/ D2 弹性自旋命中（&lt;2s，无需门铃和 syscall）/ D3 批处理追加 / D4 竞态兜底。</li><li>X100 的共享窗映射<strong>实际为 cacheable</strong>（PTE PBMT 不生效），跨核一致性完全依赖 fence/CBO 同步点——这是所有 fence 开销的根本来源，也是附录 B 正确性问题的根源。</li></ul><hr><h2 id="_2-总预算-240μs-花在哪-图-1" tabindex="-1">2. 总预算：240µs 花在哪（图 1） <a class="header-anchor" href="#_2-总预算-240μs-花在哪-图-1" aria-label="Permalink to &quot;2. 总预算：240µs 花在哪（图 1）&quot;">​</a></h2><p><img src="`+a+'" alt="图1"></p><p>D1 路径六段（dd 场景闭环恒等式 <code>rtt = send + ddrain + ddisp + dseen + S + APret</code>，残差 0.0）：</p><table tabindex="0"><thead><tr><th>段</th><th>含义</th><th>实测 µs</th><th>内部构成</th></tr></thead><tbody><tr><td>send</td><td>AP 用户态写入与发布</td><td>8.5</td><td>user-cbo 按行发布（槽 4 行 + 索引 1 行）+ BUSY 判定，D2 路径零 syscall</td></tr><tr><td>ddrain</td><td>RP 中断服务中的 mailbox 处理</td><td>3.6</td><td>mailbox FIFO 排空 + latch（timer 直连优化后由 11.3 降至该值）</td></tr><tr><td>ddisp</td><td>trap+调度+MSIP 写生效</td><td>27.1</td><td>含 MSIP 写经互连生效（约 54µs 物理下限）的分摊 + 执行器派发（ISR 直派已否决——处理必须留在 task 上下文，此段为 rt-async 任务模型的结构性成本）</td></tr><tr><td>dpre</td><td>发现前缀</td><td>24.3</td><td>set_busy(2.2) + ch2 空查(6.6) + <strong>mtime 时间戳开销（约 14）</strong> + 链路</td></tr><tr><td>drx</td><td>try_recv 取包</td><td>45.6</td><td>3 次 Acquire 读(6.6) + 槽读(1.2) + Release 写(2.2) + <strong>mtime 时间戳开销（约 24）</strong>，真实执行约 20</td></tr><tr><td>dserde</td><td>分发与反序列化</td><td>38.0</td><td>method_id(1.1) + dispatch/postcard(约 10) + <strong>mtime 时间戳开销（约 24）</strong>，真实执行约 11</td></tr><tr><td>S</td><td>服务尾+响应+回程门铃</td><td>67.7</td><td>handler 余下部分 + 响应 try_send(16.6) + notify(3.4) + AP 内核唤醒 Y≈54（物理下限）</td></tr><tr><td>APret</td><td>AP 唤醒回收</td><td>25.3</td><td>IRQ→调度→用户态→读响应</td></tr></tbody></table><p><strong>表中数值的解读</strong>：dpre/drx/dserde 是包含时间戳读取开销的测量值——每段边界那次 mtime 读 与上一次读之间有间隔，支付的是 24.5µs 冷读价格而非 106ns 热读价格。剥离这部分后的 RP 真实执行见 §4 图 3。<strong>D2 路径</strong>（189µs）：send 8.8 + 自旋发现（半周期约 9µs）+ RP 真实 处理约 70-90 + AP 收尾——RP 侧构成相同，只是唤醒方式换成了轮询粒度。</p><hr><h2 id="_3-每种操作的实测单价-图-2" tabindex="-1">3. 每种操作的实测单价（图 2） <a class="header-anchor" href="#_3-每种操作的实测单价-图-2" aria-label="Permalink to &quot;3. 每种操作的实测单价（图 2）&quot;">​</a></h2><p><img src="'+o+'" alt="图2"></p><h3 id="_3-1-数据搬运-无内存序的普通访存-——都很便宜" tabindex="-1">3.1 数据搬运（无内存序的普通访存）——都很便宜 <a class="header-anchor" href="#_3-1-数据搬运-无内存序的普通访存-——都很便宜" aria-label="Permalink to &quot;3.1 数据搬运（无内存序的普通访存）——都很便宜&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>单价</th><th>说明</th></tr></thead><tbody><tr><td>普通读 SRAM 同址</td><td>22ns</td><td>前端合并效应（连续读同一地址被合并）</td></tr><tr><td>普通读 SRAM 顺序跨行</td><td>195ns</td><td>流水后</td></tr><tr><td>普通读 SRAM 冷跨行（512B 步进）</td><td>417-520ns</td><td>无流水</td></tr><tr><td><strong>256B 消息槽整块读</strong></td><td><strong>1.2µs</strong></td><td>try_recv 的取包成本</td></tr><tr><td><strong>256B 消息槽整块写</strong></td><td><strong>6.3µs</strong></td><td>写路径无合并（由 send_seq 推算）——写比读贵 5 倍</td></tr><tr><td>mailbox 寄存器读</td><td>148-196ns</td><td>主域窗口 148 / 本地窗口 180</td></tr></tbody></table><h3 id="_3-2-内存序-fence-——主要开销之一" tabindex="-1">3.2 内存序（fence）——主要开销之一 <a class="header-anchor" href="#_3-2-内存序-fence-——主要开销之一" aria-label="Permalink to &quot;3.2 内存序（fence）——主要开销之一&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>单价</th><th>实际指令序列</th></tr></thead><tbody><tr><td>Acquire 原子读</td><td><strong>2198ns</strong></td><td><code>ld</code> + <code>fence r,rw</code>（并非原子指令）</td></tr><tr><td>Release 原子写</td><td><strong>2222ns</strong></td><td><code>fence rw,w</code> + <code>sd</code></td></tr><tr><td>纯 fence</td><td>约 2095ns</td><td>四种变体（r,rw / rw,w / rw,rw / iorw,iorw）同价</td></tr><tr><td>本地原子 RMW（P1 CS 后端）</td><td><strong>约 90ns</strong></td><td><code>csrrci mstatus,8</code> + 普通 ld/sd，P1 的成果</td></tr></tbody></table><p><strong>规律</strong>：fence 的耗时与冷热、地址、目标（共享窗或本地 .bss）均无关，恒定为 2.1-2.2µs。 RP 对窗口无缓存（读到即真值），但不使用 fence 的普通读会被前端合并缓冲固定在陈旧值上 （litmus L1：200 次中 0 次读到新值）——因此跨核读必须使用 fence，不存在免费的刷新方式 （邻址读、CBO 替代方案均无效或未经验证）。</p><h3 id="_3-3-计时器——主要开销之二-本次工作最大的意外" tabindex="-1">3.3 计时器——主要开销之二（本次工作最大的意外） <a class="header-anchor" href="#_3-3-计时器——主要开销之二-本次工作最大的意外" aria-label="Permalink to &quot;3.3 计时器——主要开销之二（本次工作最大的意外）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>单价</th><th>说明</th></tr></thead><tbody><tr><td>mtime MMIO 读（热循环）</td><td>106ns</td><td>背靠背流水价格</td></tr><tr><td><strong>mtime MMIO 读（非背靠背）</strong></td><td><strong>约 24.5µs</strong></td><td>跨时钟域同步器重新锁定，231 倍；任意非背靠背间隔都会触发（poll 间隔几十 ns 同样算冷——now_gapped 每轮 69µs，见 §6.8）</td></tr><tr><td>mcycle CSR 读（热）</td><td><strong>17ns</strong></td><td>4 cycle/次，CSR 本地读无 MMIO</td></tr><tr><td>mcycle CSR 读（间隔约 400µs）</td><td><strong>约 2.9ms</strong></td><td>冷读开销是 mtime 的 118 倍；但计数频率为<strong>核频 245.84MHz</strong>（cycle_cal 联标 1,229,222c/5ms，与 mtime 不同源）——属于&quot;仅冷读慢&quot;的类型：测量 stamp 链可改用 mcycle 并在段间保持活跃（保温读取仅 17ns），生产环境每消息级间隔计时不可用冷读</td></tr><tr><td><strong>soc-timer counter1（0xd4016094）</strong></td><td>背靠背 277ns；<strong>间隔读约 13µs</strong></td><td>AP 域 APB 块，12.8MHz 自由运行（mux=0）。更换计时源方案经真板测试证伪（08-22，6f4ec9d 回滚）：277ns 是流水价格，真实路径中读取间隔为 µs 级时每次仍触发约 13µs 的重锁开销，整条链 8 次读取合计反而更慢（rtt 240→248.5 实测证实）；驱动已删除（dfb8b5e，timer_k3 改为本地域）</td></tr><tr><td><strong>AON_TIMER1（0xc0889000，本地域）</strong></td><td>背靠背 <strong>4ns</strong>；纯本地间隔读<strong>约 1.9µs</strong>；生产路径间隔读约 10µs</td><td>RCPU AON 域专属。真板验证：计数递增，实测 <strong>2.0001MHz</strong>（文档标称 SEL=0 为 25.6MHz，与实测不符）。生产迁移第二次证伪并回滚（05691b0）——原因见&quot;探针结果不等于生产结果&quot;，详见 §6.2</td></tr></tbody></table><p><strong>推论</strong>：每条消息的计时与统计链（step 计时、SVC 统计、弹性窗计时、测量构建的 stamp 链） 中存在若干次间隔较长的冷读，每次实际等待约 24µs。测量构建每消息 6-8 次（40-70µs）；生产 构建只有 2-4 次（24-48µs）。</p><h3 id="_3-4-门铃-中断与计算" tabindex="-1">3.4 门铃/中断与计算 <a class="header-anchor" href="#_3-4-门铃-中断与计算" aria-label="Permalink to &quot;3.4 门铃/中断与计算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>单价</th></tr></thead><tbody><tr><td>门铃 notify（fence + mailbox MMIO 写）</td><td>3.46µs</td></tr><tr><td>postcard 序列化+反序列化双向（PING 形状）</td><td>9.4µs</td></tr><tr><td>dispatch 全程（宏 match+反序列化+handler+响应构造）</td><td>18.2µs（op 内热态价格）</td></tr><tr><td>MSIP 写经互连生效</td><td>约 54µs（物理下限，rtbench sec8 定论）</td></tr></tbody></table><hr><h2 id="_4-rp-侧处理一条消息的逐项分解-图-3" tabindex="-1">4. RP 侧处理一条消息的逐项分解（图 3） <a class="header-anchor" href="#_4-rp-侧处理一条消息的逐项分解-图-3" aria-label="Permalink to &quot;4. RP 侧处理一条消息的逐项分解（图 3）&quot;">​</a></h2><p><img src="'+n+'" alt="图3"></p><p><strong>左柱：测量构建的实测三段（108µs）</strong>——每段混入了段边界那次 mtime 冷读（约 24µs/次）。 <strong>中柱：剥离后的真实执行（约 91µs）</strong>，逐项如下：</p><table tabindex="0"><thead><tr><th>环节</th><th>操作序列</th><th>次数</th><th>小计</th></tr></thead><tbody><tr><td>弹性前缀</td><td>set_busy(Release 2.2) + ch2 空查(3 次 Acquire 6.6) + 链路</td><td>4 次 fence</td><td>约 11µs</td></tr><tr><td><strong>取包 try_recv</strong></td><td>magic Acquire + read Acquire + write Acquire + 槽读 1.2 + read Release</td><td><strong>4 次 fence + 1 次块读</strong></td><td><strong>约 20µs</strong></td></tr><tr><td>分发</td><td>method_id + 宏 match + postcard 反序列化</td><td>纯计算</td><td>约 11µs</td></tr><tr><td><strong>响应 try_send</strong></td><td>magic Acquire + write Acquire + read Acquire + 槽写 6.3 + write Release</td><td><strong>4 次 fence + 1 次块写</strong></td><td><strong>约 15µs</strong></td></tr><tr><td>响应门铃</td><td>notify = fence + MMIO 写</td><td>1 次</td><td>3.4µs</td></tr><tr><td>收尾 ch2 再查</td><td>3 次 Acquire</td><td>3 次 fence</td><td>6.6µs</td></tr><tr><td>生产计时开销</td><td>step/SVC 计时 1-2 次冷 mtime 读</td><td>1-2 次</td><td>约 24µs</td></tr><tr><td><strong>合计</strong></td><td></td><td><strong>约 14 次 fence</strong></td><td><strong>约 91µs</strong></td></tr></tbody></table><p>其中的<strong>结构性冗余</strong>（P3 的优化对象）：magic 每次都检查（运行期不会变化）、read/write 索引 中有一半是本核自己写的数据（RP 是唯一写者，不加 fence 也能读到最新值）、ch2 在前后做两次 完整检查。 <strong>右柱：P3 当时的理论目标约 42µs</strong>——实际兑现情况：didx 7.6→3.1µs（3 次减为 1 次 Acquire， 与预期精确一致）、消息级 −10µs、自旋 18→9.4µs/轮（§6.3）。</p><hr><h2 id="_5-排查过程-九个候选假设与最终结论-图-4" tabindex="-1">5. 排查过程：九个候选假设与最终结论（图 4） <a class="header-anchor" href="#_5-排查过程-九个候选假设与最终结论-图-4" aria-label="Permalink to &quot;5. 排查过程：九个候选假设与最终结论（图 4）&quot;">​</a></h2><p><img src="'+c+'" alt="图4"></p><p>针对约 32µs 的缺口（探针合计无法解释的 drx/dserde 超出部分），逐一排查了九个假设：</p><table tabindex="0"><thead><tr><th>假设</th><th>判定实验</th><th>结果</th></tr></thead><tbody><tr><td>H1 fence 冷热单价差异</td><td>Acquire 四种口径（同址热/跨址/间隔/本地）</td><td>排除：全部 2198-2215ns</td></tr><tr><td>H2 postcard 反序列化慢</td><td>postcard_rt</td><td>排除：双向共 9.4µs</td></tr><tr><td>H4 WFI 冷核执行惩罚</td><td>dd 100ms 间隔（D2 热态）</td><td>排除：svc/drx 与 D1 冷态同价</td></tr><tr><td>H5 真实通道地址溢价</td><td>self_round（真实 ch0 自往返）</td><td>排除：与 scratch 复刻之和相同（差 1%）</td></tr><tr><td>H7 冷取指/冷执行</td><td>dd warm_gap（测量前 300µs 预热同路径）</td><td>排除：drx 43.7 无变化</td></tr><tr><td>H8 新写入数据的读取延迟</td><td>fresh 衰减扫描（间隔 D 从 0 到 50ms）</td><td>排除：D=0 时仅 11.4µs，且大部分是时间戳自身引入的误差</td></tr><tr><td>H9 AP 内核活动竞争</td><td>spin-await（AP 零 syscall 零调度）</td><td>排除：drx 仍为 43.5；<strong>附带发现：W2 实测 −11µs</strong></td></tr><tr><td><strong>最终确认：mtime 冷读</strong></td><td><strong>now_gapped</strong></td><td>成立：间隔 20µs 时单次 24.5µs，同时解释了 dslot 37.2（=槽读 12 + 时间戳 24）、drest 34.0（=dispatch 10 + 时间戳 24）、didx 7.8 较小（间隔 8µs 未超过阈值）的完整对称关系</td></tr></tbody></table><p>判断过程的核心逻辑：同一操作在探针中 11.7µs、在真实路径中 43.6µs，预热不能降低、AP 休眠也不能降低——说明额外开销在 RP 内部，且与相邻两次计时器读取的间隔有关。now_gapped 实验证实了这一点。</p><p><strong>附：过程中意外发现并修复的三个隐藏缺陷</strong>（详见附录 A）：槽区布局偏移错误 0xF0（sizeof 断言无法区分）、AP 按行刷新错位（被内核行为掩盖导致贡献被高估）、<code>csrr cycle</code> 在 M 态 未实现（Illegal Instruction）。</p><hr><h2 id="_6-优化路线图-图-5" tabindex="-1">6. 优化路线图（图 5） <a class="header-anchor" href="#_6-优化路线图-图-5" aria-label="Permalink to &quot;6. 优化路线图（图 5）&quot;">​</a></h2><p><img src="'+i+'" alt="图5"></p><h3 id="_6-1-进展一览与叠加预期" tabindex="-1">6.1 进展一览与叠加预期 <a class="header-anchor" href="#_6-1-进展一览与叠加预期" aria-label="Permalink to &quot;6.1 进展一览与叠加预期&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>项</th><th>说明</th><th>收益</th></tr></thead><tbody><tr><td>已合入</td><td>P1</td><td>单核原子 CS 后端 + timer 直连 + 本地别名窗 + mailbox 去 Acquire</td><td>294→240（D1）/ 209→189（D2）</td></tr><tr><td>已证伪</td><td><s>更换计时源</s></td><td>counter1、AON_TIMER1 两次真板测试均证伪并回滚；计时源在生产路径中性（§6.2）</td><td>无收益也无损失</td></tr><tr><td>已验收</td><td>P3 fence 去冗余</td><td>magic 与自产索引 Relaxed 化，对端可见性协议零妥协（§6.3）</td><td>−10µs/消息 + 自旋 −8.6µs/轮</td></tr><tr><td>已定性</td><td>A4 缓存写回丢失</td><td>cbo.flush 静默丢发布，四个阶段查明并验证恢复可行性（附录 B）；按设计决策不设运行时恢复，fresh_scan 兼作存在性检测</td><td>正确性（非延迟项）</td></tr><tr><td>待实施</td><td>W2 双向轮询</td><td>AP 响应方向用户态自旋，绕过 MSIP 约 54µs 的物理下限（§6.5）</td><td>−11µs 起步</td></tr><tr><td>已否决</td><td><s>P2 ISR 直派</s></td><td>不破坏 rt-async 任务模型（§6.6）</td><td>—（预期 −22µs 放弃）</td></tr><tr><td>远期</td><td>硬件</td><td>mailbox 载荷直传小消息 / 硬件 spinlock（0xCAC9_1C00，手册确认存在）</td><td>更进一步</td></tr></tbody></table><p>叠加预期（不含已否决与已证伪项）：<strong>D1 240→230（P3 已验收）→约 219（W2 之后），D2 189→约 179→约 168</strong>。再往下就是 SPSC 协议本体（每消息 4 次 fence，约 8.8µs）+ 数据搬运 （约 7.5µs）+ 任务模型结构性成本（ddisp 约 27µs）构成的物理下限区域。</p><h3 id="_6-2-更换计时源-已证伪-两次失败与启动环境差异的确认" tabindex="-1">6.2 更换计时源（已证伪）：两次失败与启动环境差异的确认 <a class="header-anchor" href="#_6-2-更换计时源-已证伪-两次失败与启动环境差异的确认" aria-label="Permalink to &quot;6.2 更换计时源（已证伪）：两次失败与启动环境差异的确认&quot;">​</a></h3><p><strong>counter1 一轮（08-21 判断可行，08-22 真板证伪）</strong>：探针全部达标（12.8MHz 自由运行、 热读 277ns）→ 迁移 → rtt 240.0→248.5 反而变差。原因：277ns 是背靠背流水价格，真实路径中 读取间隔为 µs 级时每次仍有约 13µs 的重锁开销（12.8MHz 计数时钟到 RCPU 总线同样跨时钟 域，程度轻于 mtime，但整条链 8 次读取合计为净损失）。已回滚（6f4ec9d），驱动删除 （dfb8b5e）。 <strong>AON_TIMER1 一轮（08-22）</strong>：本地域新候选，探针达标（实测 2.0001MHz、热读 4ns 为全系统 最快、纯本地间隔读开销约 1.9µs）→ 迁移（eb2da18）→ rtt 251.5，当时看似&quot;更差&quot;→ 回滚后 复测（mtime 版固件）rtt 仍约 249——与 counter1 轮（248.5）、AON 轮（251.5）三轮数据的 统计特征一致，据此修正结论：<strong>+11µs 全部来自启动间的环境差异漂移</strong>（send 段 8.5→14.4 在三轮中恒定，作为佐证），<strong>计时源在生产路径是中性的</strong>——mtime 的 24.5µs 冷读开销在 真实路径中被交织的 SHM/fence 访存流量保持了路径活跃，从未实际支付（没有可节省的开销）， 替换计时器也没有额外代价。回滚（05691b0），更换计时源的方案关闭。</p><p>由此固化两条规则：</p><ul><li><strong>探针结果不等于生产结果</strong>——探针只用于筛选，优化验收只认生产 dd 数据；</li><li><strong>dd 对比只认同一次启动内的 A/B</strong>——跨启动存在环境差异漂移（send 段 +6、RP 段 +5；同一 次启动内非常稳定，σ=0.16µs；推测与热状态、频率、加载地址等因素有关，尚未定位）。</li></ul><p>timer_k3 驱动与 tmr_aon_* 探针保留：AON_TIMER1 本身是有价值的发现（可用的本地域 2MHz 计数器，可作为短间隔测量的备选）。</p><h3 id="_6-3-p3-已验收-fence-去冗余-−10μs-消息-08-22-08-11-轮验收" tabindex="-1">6.3 P3（已验收）：fence 去冗余（−10µs/消息，08-22 08:11 轮验收） <a class="header-anchor" href="#_6-3-p3-已验收-fence-去冗余-−10μs-消息-08-22-08-11-轮验收" aria-label="Permalink to &quot;6.3 P3（已验收）：fence 去冗余（−10µs/消息，08-22 08:11 轮验收）&quot;">​</a></h3><p>在 SPSC 单写者论证成立的前提下，<strong>降低结构性冗余的 fence 强度</strong>：magic 改为 Relaxed （运行期不变量，mapping 建立时的屏障已覆盖）、自产索引改为 Relaxed（RP 是唯一写者，不加 fence 也能读到最新值）；<strong>对端索引的 Acquire 读与发布的 Release 写原样保留——数据可见性 协议没有任何妥协</strong>。</p><p>验收数据：didx 7.6→3.1µs（σ=0.02，3 次减为 1 次 Acquire，与预期精确一致）、drx 48.2→43.5、dpre 25.1→20.6、<strong>同一次启动内 A/B（send≈14.5 的同一环境条件）rtt 246.9→236.9（−10.0µs）</strong>、自旋 18→9.4µs/轮（spin_iter 17997→9420ns，D2 收益）。实现 位于 ov-channels b45bc0a + ov-rpc stamps 对齐（508be4b）+ 主仓指针（bd662e7）。 过程中的曲折：ov-rpc server.rs 的 stamps 手写展开取包序列是 ov-channels 的逐条复刻， 修改内存序必须在两处同步（首轮遗漏对齐导致 didx 不变，已修正）。</p><h3 id="_6-4-a4-cbo-flush-静默丢发布-已定性-处置-检测而非恢复-详见附录-b" tabindex="-1">6.4 A4：cbo.flush 静默丢发布（已定性；处置 = 检测而非恢复，详见附录 B） <a class="header-anchor" href="#_6-4-a4-cbo-flush-静默丢发布-已定性-处置-检测而非恢复-详见附录-b" aria-label="Permalink to &quot;6.4 A4：cbo.flush 静默丢发布（已定性；处置 = 检测而非恢复，详见附录 B）&quot;">​</a></h3><p>优化过程中发现的 X100 cbo.flush 静默丢发布问题：AP 写入的环索引偶尔永远到不了 SRAM， RP 无法读到，造成消息丢失甚至挂死。查明经历了四个阶段：同核回读检测被证伪 → 纯重发被 &quot;粘滞&quot;现象证伪 → <strong>重写同值形成新脏行再发布</strong>（republish）消除粘滞 → v2 修复了读索引 回退的隐患。验证（08-23 04:19 轮）：fresh_scan 全部通过、mb 无幻影消息、dd 无额外 开销（rtt 237.7，与 236.9 基线一致；闭环残差 0.0/30）。<strong>收尾时的设计决策（08-23）： 上述验证用的恢复机制整体移除，不设运行时恢复</strong>——发送路径保持单遍发布，IPI 等待挂死由 bench 既有心跳超时（SIGALRM 10s）诊断退出；fresh_scan 改造为 A4 存在性检测测试（超时档 交叉 AP 缓存 / RP SRAM / AP 失效回读三方索引视角，逐档判定，见附录 B.6）。</p><h3 id="_6-5-w2-待实施-双向轮询" tabindex="-1">6.5 W2（待实施）：双向轮询 <a class="header-anchor" href="#_6-5-w2-待实施-双向轮询" aria-label="Permalink to &quot;6.5 W2（待实施）：双向轮询&quot;">​</a></h3><p>AP 响应方向改为用户态自旋（不再使用 AWAIT 系统调用与内核唤醒），spin_await 预演已实测 rtt 189→178（零固件改动）。代价是持续占用一个 AP 核心，作为延迟关键模式提供。轮询循环 自带超时判定，A4 类丢发布在其中表现为超时而非挂死。</p><h3 id="_6-6-已否决的-p2-与远期硬件选项" tabindex="-1">6.6 已否决的 P2 与远期硬件选项 <a class="header-anchor" href="#_6-6-已否决的-p2-与远期硬件选项" aria-label="Permalink to &quot;6.6 已否决的 P2 与远期硬件选项&quot;">​</a></h3><p>P2（响应在 ISR 内直接写完）否决（2026-08-21）：不破坏 rt-async 的任务模型——实际处理 必须留在 task 上下文（executor/waker 语义），ISR 只做唤醒和标记；ddisp 27.1µs 作为结构 性成本保留。远期：mailbox 载荷直传小消息（数据随门铃直接传递）、硬件 spinlock （0xCAC9_1C00，手册确认存在）。</p><h3 id="_6-7-本地域优先原则-2026-08-22-定案-后续外设选型遵守" tabindex="-1">6.7 本地域优先原则（2026-08-22 定案，后续外设选型遵守） <a class="header-anchor" href="#_6-7-本地域优先原则-2026-08-22-定案-后续外设选型遵守" aria-label="Permalink to &quot;6.7 本地域优先原则（2026-08-22 定案，后续外设选型遵守）&quot;">​</a></h3><p>RT24 高延迟访问的根本原因是<strong>跨簇间互连</strong>——mtime（SysTimer @0xe4000000）虽然在功能上 是 rcpu1 的计时器（mtimecmp 按 hart&lt;&lt;27 分区），但物理上是全 SoC 共享块，挂在簇间互连上， 访问它必然跨越互连（间隔后的重锁开销即互连或桥空闲后的重新唤醒；热读 106ns 说明路径本身 并不慢；具体机制无文档，属未解决问题）。<strong>RT24 本地总线上的外设只有 0xc088_xxxx AON 域 这一组</strong>（06_address_map §6.2：AON_TIMER1~4、mailbox、PWM 等）。凡是高频访问的外设 （计时、自旋索引），应尽可能用本地域替代外部域。 附带解决了此前&quot;rtimer0 无法工作&quot;的未解问题：原因不是域过滤，而是 <code>MCU_TIMER1_CLK_RST</code>（0xc088c04c）bit0 TIMER_SW_RSTN 为<strong>低有效</strong>（复位值 0 表示保持在 复位状态），当时按 APBC 高有效的惯例先后写入 0x7 和 0x3，第二次写入清除了 bit0，把外设 重新保持在复位状态。</p><h3 id="_6-8-计时器专题附记" tabindex="-1">6.8 计时器专题附记 <a class="header-anchor" href="#_6-8-计时器专题附记" aria-label="Permalink to &quot;6.8 计时器专题附记&quot;">​</a></h3><ul><li><strong>mcycle 三项定论</strong>（08-21 真板）：热读 17ns（4 cycle，CSR 本地）、频率 <strong>245.84MHz， 即核频</strong>（约 491.52/2；此前&quot;与 mtime 同源 24MHz&quot;的说法被证伪）、间隔读约 2.9ms（是 mtime 的 118 倍）——属于&quot;仅冷读慢&quot;的类型：测量 stamp 链可改用 mcycle 并在段间保持活跃 （保持用的读取仅 17ns），生产环境每消息级间隔计时不可用冷读。</li><li><strong>mtime 开销模型的修正</strong>：now_gapped 每轮 69µs（t0 与首个 poll 各支付一次 24.5µs 冷读 价格）证明 <strong>mtime 冷读由&quot;任意非背靠背间隔&quot;触发</strong>（poll 间隔几十 ns 也算冷）；而 tmr_gapped 在 t1 前插入一次其他设备的读（counter1 277ns）后每轮仅 22.4µs——mtime 的 读取全部变热。机制尚未解释（推测与流水线或前端行为有关），留待后续研究。</li></ul><hr><h2 id="_7-测量方法与可信度" tabindex="-1">7. 测量方法与可信度 <a class="header-anchor" href="#_7-测量方法与可信度" aria-label="Permalink to &quot;7. 测量方法与可信度&quot;">​</a></h2><ul><li><strong>dd 场景</strong>：AP 双时钟戳（内核 RD_KTS）与 RP mtime 戳交叉，使用与两钟相位差无关的恒等式（S 与 AP 回程），闭环残差 30/30 = 0.0。</li><li><strong>mb 场景</strong>：MEMBENCH RPC 共 35 个微基准操作，含热循环、间隔变体与真实通道自往返。</li><li><strong>litmus L1/L2/L3</strong>：检验免 fence 顺序性的正反对照实验，全部通过。</li><li><strong>已知的测量问题</strong>（本文已修正或标注）：mtime 时间戳开销污染分段、T_SCHED 连续执行流不刷新（D2 下 dpre/dseen 失效）、fresh_scan 列错位、判读函数 g() 索引差一。</li><li><strong>规则</strong>：探针结果不等于生产结果（§6.2）；dd 对比只认同一次启动内的 A/B（§6.2）。</li><li><strong>未修复的已知问题</strong>：AP 侧退出时段错误（0xffffff00 前缀 EXECUTE，每场景开头与退出各一次，数据有效）；SIGALRM 无法打断内核 AWAIT（bench 以心跳看门狗加 SIGALRM 兜底）；send 段跨启动漂移未定位（§6.2）；s4/s6 回归未跑（P3 修改了内存序，建议补充）。</li></ul><h2 id="_8-数据溯源" tabindex="-1">8. 数据溯源 <a class="header-anchor" href="#_8-数据溯源" aria-label="Permalink to &quot;8. 数据溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>场景/轮次</th><th>关键值</th></tr></thead><tbody><tr><td>P1 后 D1 分解</td><td>dd 30 轮（08-20）</td><td>rtt 240.0 / drx 45.6 / dserde 38.0 / svc 130-135</td></tr><tr><td>D2 热态</td><td>dd 100ms 间隔 ×3 轮</td><td>drx 43.5±0.4 / dserde 34.4 / svc 130.8</td></tr><tr><td>细分四段</td><td>dd + stamps 6 槽（08-21）</td><td>didx 7.8 / dslot 37.2 / dmth 1.1 / drest 34.0</td></tr><tr><td>单价表</td><td>mb（08-20/21 两轮复测）</td><td>全部 ±1% 复现</td></tr><tr><td>H8 衰减扫描</td><td>mb fresh_scan（修正列错位后）</td><td>23.0→11.6µs</td></tr><tr><td>mtime 定论</td><td>mb now_gapped</td><td>每轮 69µs = 20µs 忙等 + 2×24.5µs 冷读</td></tr><tr><td>mcycle 三项定论</td><td>mb cycle_hot/cycle_cal/cycle_gapped（08-21）</td><td>热 4158c/千次=17ns；245.84MHz（核频）；间隔读约 2.9ms/次（每轮 wall 6.18ms − 忙等 393µs = 2 次）</td></tr><tr><td>soc-timer 判定不可用</td><td>mb tmr_setup/gapped/cal/b_scan（08-21）</td><td>CER 写入不生效（cer=0 / retries=8）；counter1 5ms 计数为 0；热读 277ns/次；d4014000 全零</td></tr><tr><td>mtime 模型修正</td><td>mb now_gapped 与 tmr_gapped 对比</td><td>69µs vs 22.4µs/轮——t1 前插入一次其他设备读（277ns）使 mtime 全部变热（机制待查）</td></tr><tr><td>W2 预演</td><td>BENCH_SPIN_AWAIT=1 dd</td><td>rtt p50 178.1（σ4.1）</td></tr><tr><td>P3 验收</td><td>dd 30 轮（08-22 08:11，同一次启动内 A/B）</td><td>rtt 246.9→236.9 / didx 7.6→3.1 / spin_iter 17997→9420ns</td></tr><tr><td>更换计时源三轮</td><td>dd（08-22 counter1/AON/回滚）</td><td>248.5 / 251.5 / 约 249，三轮统计特征一致——确认为启动环境差异</td></tr><tr><td>A4 第三阶段验收</td><td>mb fresh_scan（08-23 04:06/04:19）</td><td>8 个间隔档全部 got=1（D=100µs 历史上连续三次丢失的档位转为成功收取）；无 stray</td></tr><tr><td>A4 最终回归</td><td>dd 30 轮（08-23 04:19）</td><td>rtt p50 237.7 / 闭环 0.0/30 / didx 3.1 保持 / 测量 30 轮零恢复</td></tr></tbody></table><hr><h2 id="附录-a-过程中意外发现并修复的三个隐藏缺陷" tabindex="-1">附录 A：过程中意外发现并修复的三个隐藏缺陷 <a class="header-anchor" href="#附录-a-过程中意外发现并修复的三个隐藏缺陷" aria-label="Permalink to &quot;附录 A：过程中意外发现并修复的三个隐藏缺陷&quot;">​</a></h2><ol><li><strong>槽区布局偏移错误 0xF0</strong>：<code>Message</code> 为 <code>align(256)</code>，<code>RingBuffer.buffer</code> 被对齐填充到 +0x100 而非通常假设的 +0x10；sizeof 断言对两种布局取整后相同（0x8100），无法区分。修复：以 <code>ov_channels::RB_SLOTS_OFF</code> 作为布局唯一依据，并添加主机端回归测试。</li><li><strong>AP 按行缓存刷新错位</strong>（user-cbo 的 <code>refresh_slot</code> 使用了错误的 SLOTS_OFF）：错位 0xF0 期间一直依靠内核 AWAIT 的 invalidate 掩盖——&quot;按行精确刷新&quot;的优化贡献此前被高估。随问题 1 一并修复。</li><li><strong><code>csrr cycle</code> 在 M 态未实现</strong>：用户态别名 CSR 触发 Illegal Instruction 导致固件崩溃；改用 <code>mcycle</code>（0xB00）。</li></ol><h2 id="附录-b-a4-问题记录——cbo-flush-静默丢发布-四个阶段-08-21-至-08-23" tabindex="-1">附录 B：A4 问题记录——cbo.flush 静默丢发布（四个阶段，08-21 至 08-23） <a class="header-anchor" href="#附录-b-a4-问题记录——cbo-flush-静默丢发布-四个阶段-08-21-至-08-23" aria-label="Permalink to &quot;附录 B：A4 问题记录——cbo.flush 静默丢发布（四个阶段，08-21 至 08-23）&quot;">​</a></h2><h3 id="b-1-问题发现与定位-08-21-夜" tabindex="-1">B.1 问题发现与定位（08-21 夜） <a class="header-anchor" href="#b-1-问题发现与定位-08-21-夜" aria-label="Permalink to &quot;B.1 问题发现与定位（08-21 夜）&quot;">​</a></h3><p>fresh_scan 探针（控制&quot;AP 写入 dummy 消息&quot;与&quot;RP 自旋收取&quot;之间的间隔 D）发现：D=100µs 档 的 dummy 消息 RP 在 200ms 内始终收不到，三轮稳定复现。关键数据：超时时 <strong>AP 缓存视角在 发布后为 (r=118, w=120)，而 SRAM/RP 视角仍为 (119,119)</strong>——AP 对索引行执行的 <code>publish</code> （fence → cbo.flush → fence）没有把新的 write 值写回 SRAM。排除了&quot;同一 cache line 数据被 旧值写回覆盖&quot;的另一种可能。这是 user-cbo 发布链的<strong>真实正确性缺陷</strong>：X100 用户态的 cbo.flush 对在途 store 存在静默丢失的可能（推测原因是 store 尚在写缓冲中时，flush 清洗到 的是旧行）。08-22 13:09 轮该问题首次在生产路径出现：寄存器探测 rd#44 收到杂散 Notification → 空唤醒 → 强制刷新后仍为空 → 挂死（丢失的是 AP→RP 请求索引——RP 从未见到 请求，响应自然永远不会到来）。</p><h3 id="b-2-第一阶段-发布后回读校验-被真板证伪-08-22" tabindex="-1">B.2 第一阶段：发布后回读校验，被真板证伪（08-22） <a class="header-anchor" href="#b-2-第一阶段-发布后回读校验-被真板证伪-08-22" aria-label="Permalink to &quot;B.2 第一阶段：发布后回读校验，被真板证伪（08-22）&quot;">​</a></h3><p><code>publish_verified</code>（56c79da）：索引发布点在 publish 后执行 refresh（clean+invalidate）， 再从 SRAM 回读比对，不符则重试最多 4 次。<strong>itb f6fc7682 轮证伪</strong>：fresh_scan D=100µs 仍然丢失。机制结论：<strong>同核回读由 L1/L2 服务，始终返回新值——校验恒通过、重试从未真正 触发，检测形同虚设</strong>。flush 与 clean-inval 组合既然无效，双遍 flush 等同类的 CBO 重试 方案也没有依据（重发与检测处于同一视角）；内核 S 态 flush 同样不能幸免（同一 CBO 指令， 且 PBMT 不生效，没有非缓存访问路径可用）。</p><h3 id="b-3-第二阶段-在途看门狗纯重发-被-粘滞-现象证伪-08-23-01-23-轮" tabindex="-1">B.3 第二阶段：在途看门狗纯重发，被&quot;粘滞&quot;现象证伪（08-23 01:23 轮） <a class="header-anchor" href="#b-3-第二阶段-在途看门狗纯重发-被-粘滞-现象证伪-08-23-01-23-轮" aria-label="Permalink to &quot;B.3 第二阶段：在途看门狗纯重发，被&quot;粘滞&quot;现象证伪（08-23 01:23 轮）&quot;">​</a></h3><p>此时唯一可靠的判断依据是<strong>时间</strong>：请求发出 3ms（rtt 的 10 倍以上余量）未见响应即怀疑 丢失，执行幂等重发布（refresh_before_send + publish_send），并根据 BUSY 状态补充门铃， 以 1ms 周期连续重试（b95e950/894f358）。幂等安全性：单请求在途协议下，重发时索引行要么 是干净的（重发无操作）要么是脏的（发布必然未生效，因此 RP 未消费，行内 read 字段与 RP 一致）——二者必居其一，不存在把 RP 已推进的消费进度倒退回去的窗口；恢复线程与主线程 发送段通过 ROUND_LOCK 互斥（避免&quot;已写槽未发布&quot;期间索引被提前发布的乱序窗口）。</p><p>真板结果：看门狗机制本身正常（mb 全套完成、无挂死），但主要目标失败——<strong>D=100µs 的丢 发布经约 200 次重发仍未生效</strong>（RP 在整个 200ms 自旋期间始终未收到）⇒ 丢失的行对 AP 侧 重复 CBO 呈现<strong>粘滞</strong>特性，&quot;重试收敛&quot;的设想被证伪。关键线索：紧邻的 D=300µs（包含<strong>新 store</strong> 的正常发送）立即成功 ⇒ 粘滞状态与旧 store 留下的行状态绑定，<strong>新的写入可以消除 粘滞</strong>。</p><h3 id="b-4-第三阶段-重写同值再发布-验收通过-08-23-04-06-轮" tabindex="-1">B.4 第三阶段：重写同值再发布，验收通过（08-23 04:06 轮） <a class="header-anchor" href="#b-4-第三阶段-重写同值再发布-验收通过-08-23-04-06-轮" aria-label="Permalink to &quot;B.4 第三阶段：重写同值再发布，验收通过（08-23 04:06 轮）&quot;">​</a></h3><p><code>cache::republish</code>（86bc6fe）：先按缓存视图<strong>重写索引字段的相同值</strong>（形成新的脏行），再 执行标准发布（槽先于索引）。看门狗节拍改为指数退避（1→64ms——第二阶段对合法的长耗时 操作每 ms 误报，5 秒级的 gapped 计时操作误触发约 9000 次），并在每轮保护结束时打印本轮 恢复次数（第二阶段的全局限流打印与双流交错遗漏了关键日志，该打印使恢复次数与超时结果 直接对应）。</p><p>验收：fresh_scan <strong>8 个间隔档全部 got=1</strong>——D=100µs 这一历史上连续三次丢失的档位转为 成功收取（7.4µs，结束统计行&quot;恢复 1 次&quot;证明恢复机制在起作用）。更重要的发现：短间隔档 （0/30/100µs）本轮也都触发了恢复（3/4/1 次）并在毫秒级完成恢复 ⇒ <strong>短间隔的丢发布是 概率性常态</strong>（此前 0/30 档&quot;通过&quot;只是没有遇到丢失，D=100µs 的&quot;确定性&quot;是小样本造成的 错觉），恢复机制持续生效。mb 全套完成，无空唤醒、无 stray。</p><h3 id="b-5-第四阶段-v2-读索引回退隐患的修复与最终验证-08-23-04-19-轮" tabindex="-1">B.5 第四阶段 v2：读索引回退隐患的修复与最终验证（08-23 04:19 轮） <a class="header-anchor" href="#b-5-第四阶段-v2-读索引回退隐患的修复与最终验证-08-23-04-19-轮" aria-label="Permalink to &quot;B.5 第四阶段 v2：读索引回退隐患的修复与最终验证（08-23 04:19 轮）&quot;">​</a></h3><p><strong>隐患（第三阶段 v1 复查时发现）</strong>：v1 把 read 字段也按缓存快照重写——在&quot;干净行误报 恢复&quot;场景（mb 类合法长耗时操作超过超时阈值，该轮 slot=0/7 各 83 次）下，快照中的 read 是 RP 消费前的陈旧值，重写一旦写入 SRAM 会<strong>把 RP 已推进的消费进度倒退回去，产生幻影 消息</strong>（队列中出现的并不存在的待处理消息）；该轮恰好未出现此问题（推测被 A4 的丢失 模式本身阻止，不可依赖）。<strong>v2（10efbe1）</strong>：只快照 AP 自己拥有的 write 字段，read 在 inval 之后重新读取 SRAM 真值——无论 inval 写回了滞留的脏行还是丢弃了干净副本，均不存 在进度倒退的窗口。</p><p><strong>最终验证</strong>：v2 复跑 fresh_scan 8 个档位全部 got=1，mb 全程无 stray（未发现幻影消息）； dd n=30 全部为 D1：rtt p50 237.7 / mean 238.2（对照 P3 基线 236.9，send 14.6 属同一环境 条件——在启动间漂移规则内统计特征一致）、<strong>闭环残差 0.0/30</strong>、didx 3.1 保持——看门狗 无额外开销（测量的 30 轮零恢复零扰动；warmup 首轮的一次恢复在毫秒级完成，未进入测量 数据）。 <strong>A4 查明至此完成</strong>：同核检测证伪 → 纯重发粘滞证伪 → 重写同值消除粘滞 → 进度回退隐患修复， 全部完成（恢复载体的后续调整见 B.6）。</p><h3 id="b-6-后续调整-08-23-收尾-移除运行时恢复-改为检测测试" tabindex="-1">B.6 后续调整（08-23 收尾）：移除运行时恢复，改为检测测试 <a class="header-anchor" href="#b-6-后续调整-08-23-收尾-移除运行时恢复-改为检测测试" aria-label="Permalink to &quot;B.6 后续调整（08-23 收尾）：移除运行时恢复，改为检测测试&quot;">​</a></h3><p>按设计决策，上述恢复机制（看门狗线程、ROUND_LOCK 互斥、<code>republish</code> 原语）在收尾时整体 移除（主仓 5d475bf）：不设运行时恢复，发送路径保持单遍发布；IPI 等待的挂死由 bench 既有 的心跳超时（SIGALRM 10s，退出码 2）诊断退出。fresh_scan 改造为 A4 存在性检测测试：超时档 交叉三方索引视角——AP 缓存视角（③ 发布前后快照，w 字段 AP 自有恒见新值）、RP SRAM 视角 （超时快照，RP 整个 200ms 自旋期所见）、AP 失效回读（超时后作废索引行再读；该读可能恰好 令迟滞脏行落地，属扰动性探测，只作行驻留态参考）——逐档判定并输出结论行。RP 视角的 w 落后 AP 缓存视角的 w，即发布未跨核可见，是 A4 在位的直接证据。四个阶段的机制探索与验证 数据仍是本报告结论的依据（重试族无效、粘滞特征、短间隔丢失为概率性常态等定性结论，不随 恢复载体的移除而失效）。</p>',97)])])}const f=d(l,[["render",h]]);export{_ as __pageData,f as default};
